import React from 'react'
import Checkbox from './Checkbox'
import type { CheckboxProps } from './Input'

export default {
  title: 'Components/Checkbox',
  component: Checkbox.Input,
  subcomponents: {
    'Checkbox.Group': Checkbox.Group,
    'Checkbox.Label': Checkbox.Label,
  },
}

function Template(args: CheckboxProps & { children: string }): JSX.Element {
  return <Checkbox.Input {...args} />
}

export const Default = {
  render: Template,
  args: {
    children: 'Label',
  },
}

export function WithComplexLabel(): JSX.Element {
  return (
    <Checkbox.Input>
      <div>Complex Label</div>
      <div>With Additional Content</div>
    </Checkbox.Input>
  )
}
